impl Document {
    pub(crate) fn compare_diagnostic_contribution_set(
        &self,
        other: &Document,
        a: &DiagnosticContributionSet,
        b: &DiagnosticContributionSet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_common_properties() != b.get_common_properties() {
            return Err(format!("{path}: COMMON_PROPERTIES mismatch"));
        }
        let list_a = a.get_element_refs();
        let list_b = b.get_element_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ELEMENT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.ELEMENT_REFS[{index}] mismatch"));
            }
        }
        let list_a = a.get_service_table_refs();
        let list_b = b.get_service_table_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SERVICE_TABLE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.SERVICE_TABLE_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_ecu_instance_props(
        &self,
        other: &Document,
        a: &DiagnosticEcuInstanceProps,
        b: &DiagnosticEcuInstanceProps,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_diagnostic_protocol(
        &self,
        other: &Document,
        a: &DiagnosticProtocol,
        b: &DiagnosticProtocol,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_diagnostic_connection_refs();
        let list_b = b.get_diagnostic_connection_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: DIAGNOSTIC_CONNECTION_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.DIAGNOSTIC_CONNECTION_REFS[{index}] mismatch"
                ));
            }
        }
        if a.get_priority() != b.get_priority() {
            return Err(format!("{path}: PRIORITY mismatch"));
        }
        if a.get_protocol_kind() != b.get_protocol_kind() {
            return Err(format!("{path}: PROTOCOL_KIND mismatch"));
        }
        if a.get_send_resp_pend_on_trans_to_boot() != b.get_send_resp_pend_on_trans_to_boot() {
            return Err(format!("{path}: SEND_RESP_PEND_ON_TRANS_TO_BOOT mismatch"));
        }
        if a.get_service_table_ref() != b.get_service_table_ref() {
            return Err(format!("{path}: SERVICE_TABLE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_diagnostic_service_table(
        &self,
        other: &Document,
        a: &DiagnosticServiceTable,
        b: &DiagnosticServiceTable,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_common_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_diagnostic_connection_refs();
        let list_b = b.get_diagnostic_connection_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: DIAGNOSTIC_CONNECTION_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.DIAGNOSTIC_CONNECTION_REFS[{index}] mismatch"
                ));
            }
        }
        if a.get_ecu_instance_ref() != b.get_ecu_instance_ref() {
            return Err(format!("{path}: ECU_INSTANCE_REF mismatch"));
        }
        if a.get_protocol_kind() != b.get_protocol_kind() {
            return Err(format!("{path}: PROTOCOL_KIND mismatch"));
        }
        let list_a = a.get_service_instance_refs();
        let list_b = b.get_service_instance_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SERVICE_INSTANCE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.SERVICE_INSTANCE_REFS[{index}] mismatch"));
            }
        }
        Ok(())
    }
}
